function fixture(c,config){
  const index=cases.findIndex(item=>item.id===c.id);
  if(c.id==='MEM-009'){
 const facts=[{subject:config.user,predicate:'음료 선호',value:'차',temporal_scope:'past',evidence:'예전에는 커피보다 차를 좋아했는데'},{subject:config.user,predicate:'음료 선호',value:'커피',temporal_scope:'current',evidence:'요즘은 커피가 더 좋아'},{subject:'민수',predicate:'음료 선호',value:'차',polarity:'negative',evidence:'친구 민수는 차를 좋아하지 않아'},{subject:config.user+'·민수',predicate:'방문 계획',value:'카페',temporal_scope:'이번 주말',evidence:'이번 주말에는 민수랑 카페에 갈 생각이야'}];
 return config.extraction.id==='extract-v1'?{facts}:config.extraction.id==='extract-v2'?{intent:'mixed_statement',facts}:{intent:'mixed_statement',facts,proposed_action:'review',changes:[{previous:0,current:1,relation:'updates'}]};
 }
 const factsByCase=[
    [{subject:config.user,predicate:'음료 선호',value:'커피보다 차',evidence:'나는 커피보다 차를 더 좋아해.'}],
    [{subject:config.user,predicate:'음료 선호',value:'커피보다 차',evidence:'나는 커피보다 차를 더 좋아해.'}],
    [{subject:config.user,predicate:'음료 선호',value:'차보다 커피',evidence:'이제는 커피가 더 좋아'}],
    [],
    [{subject:config.user,predicate:'주말 활동',value:'독서',evidence:'나는 주말마다 책을 읽어.'}],
    [{subject:'서연',predicate:'거주지',value:'부산',evidence:'나는 부산에 살고 있어.'}],
    [{subject:config.user,predicate:'공간 선호',value:'조용한 곳',evidence:'조용한 곳을 좋아하고'},{subject:config.user,predicate:'주말 활동',value:'독서',evidence:'주말에는 책을 읽어'}],
    [{subject:config.user,predicate:'이름',value:'서연',evidence:'내 이름은 서연이야.'}]
  ];
  const facts=factsByCase[index];
  const intent=index===3?'delete_request':index===2?'preference_update':'fact_statement';
  if(config.extraction.id==='extract-v1')return {facts};
  if(config.extraction.id==='extract-v2')return {intent,facts};
  return {intent,facts:facts.map(f=>({...f,polarity:'positive',temporal_scope:index===2?'current':'unspecified'})),proposed_action:index===3?'delete':index===2?'update':'store'};
}
function saveSnapshot(indices){const config=getConfig();const reviews=currentHuman();const now=new Date();const run={formatVersion:1,id:'LOCAL-'+now.getTime()+'-'+Math.random().toString(36).slice(2,6),createdAt:now.toISOString(),config,kind:'demo',humanReviews:Object.fromEntries(indices.map(i=>[cases[i].id,reviews[cases[i].id]]).filter(([,value])=>value)),results:indices.map(i=>{const c={...cases[i],extraction:fixture(cases[i],config),measurement:null};return {...c,memoryStructure:buildMemoryStructure(c,config),searchStructure:buildSearchStructure(c,config),visualEvidence:buildVisualEvidence(c,config),representation:createRepresentation(c,config)}})};if(!persist([run,...runs]))return; savedRunId=run.id;render();renderHistory();refreshCollections();toast('선택한 환경과 예시 결과를 로컬에 저장했습니다.')}
function renderConfig(){const config=getConfig();$('#version-description').textContent=config.extraction.description;$('#config-summary').textContent=`${config.model.name} / ${config.extraction.name}`;$('#version-prompt').textContent=config.extraction.prompt;$('#version-fields').textContent=config.extraction.fields.join(' · ');$('#combo-count').textContent=String(activeRuns().filter(r=>configKey(r.config)===configKey(config)).length);const saved=currentRun();$('#snapshot-state').textContent=saved?`저장된 결과 · ${saved.id} · ${new Date(saved.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}`:'미저장 미리보기 · 현재 선택 환경의 고정 예시';$('#return-preview').hidden=!saved;}
function renderCases(){const saved=currentRun();const scope=saved?saved.results:cases;const visible=scope.filter(c=>(filter==='all'||(filter==='review'?c.status==='review'&&!currentHuman()[c.id]:c.status===filter))&&`${c.name} ${c.category} ${c.id}`.toLowerCase().includes(query.toLowerCase()));$('#cases').innerHTML=visible.length?visible.map(c=>`<button class="case ${cases[selected].id===c.id?'active':''}" data-case="${c.id}"><span class="status-icon ${c.status}">${symbols[c.status]}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${esc(c.category)}</small></span>${currentHuman()[c.id]?'<span class="case-time">판정 완료</span>':''}</button>`).join(''):'<div class="empty">일치하는 시나리오가 없습니다.</div>';document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{selected=cases.findIndex(c=>c.id===b.dataset.case);step=2;render()})}
function conversation(c){return `<div class="step-label"><strong>01 &nbsp; 기억 저장</strong><span>대화 A · 고정 예시</span></div><div class="bubble"><small>사용자 입력</small>${esc(c.input)}</div><div class="divider">새 대화 시작 · 이전 메시지 제외</div><div class="step-label"><strong>02 &nbsp; 기억 활용</strong><span>대화 B</span></div><div class="bubble">${esc(c.question)}</div>${step>=2?`<div class="bubble ai"><small>✳ &nbsp; MEMORY AGENT · 예시 응답</small>${esc(c.answer)}</div>`:'<div class="empty">다음 단계에서 회상 예시를 확인합니다.</div>'}`}
function criteria(c){return `<div class="criteria"><h4>자동 검사 · 고정 예시 / 실제 검사 미실행</h4><div class="check-row"><span>시나리오의 필수 조건 충족</span><span class="${c.status==='fail'?'amber':'green'}">${c.status==='fail'?'× 실패':'✓ 통과'}</span></div><div class="check-row"><span>독립된 사용자 / 대화 사용</span><span class="green">✓ 통과</span></div></div>`}
function humanReview(c){const value=currentHuman()[c.id];return `<div class="review-box"><strong>◉ &nbsp; 사람 판정 <span class="muted">· ${currentRun()?'이 실행 기록에 저장':'다음 저장 결과에 포함'}</span></strong><p>${value?`내 판정: ${value==='pass'?'통과':'실패'} · 변경할 수 있습니다.`:'기억이 답변에 자연스럽고 정확하게 반영되었나요?'}</p><div class="review-buttons"><button class="button ${value==='pass'?'primary':''}" id="human-pass">✓ 적절해요</button><button class="button ${value==='fail'?'primary':''}" id="human-fail">× 개선이 필요해요</button></div></div>`}
function renderDetail(){const c=currentCase(), saved=currentRun();const extraction=saved?c.extraction:fixture(c,getConfig());$('#detail').innerHTML=`<div class="case-id">${esc(c.id)} / ${saved?'SAVED RESULT':'PREVIEW'}</div><div class="detail-head"><h3>${esc(c.name)}</h3><span class="badge ${c.status}">${c.status==='review'&&currentHuman()[c.id]?'사람 판정 완료':labels[c.status]}</span></div><button class="button compare-current-source" data-compare-current>이 원문으로 방식 비교 ↗</button><p class="goal">${esc(c.goal)}</p><div class="detail-tabs"><button class="detail-tab ${tab==='conversation'?'selected':''}" data-tab="conversation">대화 흐름</button><button class="detail-tab ${tab==='extraction'?'selected':''}" data-tab="extraction">기억 구조</button><button class="detail-tab ${tab==='retrieval'?'selected':''}" data-tab="retrieval">검색 구조</button><button class="detail-tab ${tab==='criteria'?'selected':''}" data-tab="criteria">판정 기준</button></div>${tab==='conversation'?conversation(c):tab==='extraction'?detailStructure('memory',c,saved?.config||getConfig()):tab==='retrieval'?detailStructure('search',c,saved?.config||getConfig()):`<div class="bubble"><small>기대 동작</small>${esc(c.goal)}</div><div class="bubble"><small>판정 방식</small>형식 및 근거 검증은 자동 검사로, 추출의 의미와 답변 적절성은 사람 판정으로 확인합니다. 현재 자동 검사 값은 예시입니다.</div>`}${criteria(c)}${humanReview(c)}<div class="detail-actions"><button class="button" id="reset">↺ 처음 단계</button><div><button class="button" id="next-step" ${step>=2?'disabled':''}>다음 단계 →</button> <button class="button primary" id="run-one" ${running?'disabled':''}>▶ 개별 재생·저장</button></div></div>`;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderDetail()});$('#human-pass').onclick=()=>judge('pass');$('#human-fail').onclick=()=>judge('fail');$('#reset').onclick=()=>{step=1;tab='conversation';renderDetail()};$('#next-step').onclick=()=>{step=2;renderDetail()};$('#run-one').onclick=()=>run([selected]);restoreEvidenceSelections();}
function judge(value){const saved=currentRun();if(saved){const updated=runs.map(r=>r.id===saved.id?{...r,humanReviews:{...r.humanReviews,[cases[selected].id]:value}}:r);if(!persist(updated))return}else{human[cases[selected].id]=value}render();renderHistory();toast(saved?'사람 판정을 해당 실행 기록에 저장했습니다.':'판정을 반영했습니다. 결과 저장 시 함께 보관됩니다.')}
function card(c,i=0){return `<div class="memory-card"><div class="meta"><span>◈ &nbsp; MEM-${String(i+41).padStart(4,'0')}</span><span>예시 기억</span></div><p>${esc(c.memory)}</p><span class="tag">${esc(c.category.split(' · ')[0])}</span><small>출처: 고정 테스트 데이터 · 대화 A</small></div>`}
function renderMemory(){const c=currentCase();$('#inspector').innerHTML=`<div class="panel-title">◈ &nbsp; 기억 인스펙터 <span>예시 데이터</span></div><div class="memory-tabs"><button data-memory="before" class="${memoryTab==='before'?'selected':''}">실행 전</button><button data-memory="after" class="${memoryTab==='after'?'selected':''}">실행 후</button></div><div class="memory-caption">${memoryTab==='before'?'저장된 기억 · 0개':'저장된 기억 · '+(c.memory?'1개':'0개')}</div>${memoryTab==='before'||!c.memory?'<div class="empty">저장된 기억이 없습니다.</div>':card(c,selected)}<div class="memory-note">ⓘ 기억 상태와 응답은 고정된 예시입니다. 선택한 모델은 아직 다운로드하거나 연결하지 않았습니다.</div><div class="memory-caption">선택한 구조화 버전</div><p>${esc((currentRun()?.config||getConfig()).extraction.name)}</p><button class="button" id="show-json">구조화 JSON 보기 →</button>`;document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{memoryTab=b.dataset.memory;renderMemory()});$('#show-json').onclick=()=>{tab='extraction';renderDetail()}}
function updateStats(){const scope=currentRun()?.results||cases;$('#workbench-count').textContent=scope.length;$('#case-count').textContent=scope.length+'개';$('#nav-case-count').textContent=String(cases.length).padStart(2,'0');$('#scenario-count').innerHTML=String(scope.length).padStart(2,'0')+'<small>개</small>';$('#pass-count').innerHTML=String(scope.filter(c=>c.status==='pass').length).padStart(2,'0')+`<small>/ ${scope.length}</small>`;$('#review-count').innerHTML=String(scope.filter(c=>c.status==='review'&&!currentHuman()[c.id]).length).padStart(2,'0')+'<small>개</small>'}
function render(){renderConfig();renderCases();renderDetail();renderMemory();updateStats()}
function setBusy(value){running=value;document.querySelectorAll('.config select,#run-all,#rerun,#save-result,#return-preview').forEach(el=>el.disabled=value);$('#run-all').textContent=value?'◌ 예시 재생 중…':'▶ 전체 재생·저장';renderDetail()}
async function run(indices){if(running)return;if(!indices.length){toast('실패한 항목이 없습니다.');return}savedRunId=null;setBusy(true);try{for(const i of indices){selected=i;step=1;render();await new Promise(resolve=>setTimeout(resolve,180));step=2;render();await new Promise(resolve=>setTimeout(resolve,180))}saveSnapshot(indices)}finally{setBusy(false)}}
function counts(r){return {pass:r.results.filter(c=>c.status==='pass').length,fail:r.results.filter(c=>c.status==='fail').length,review:r.results.filter(c=>c.status==='review'&&!r.humanReviews?.[c.id]).length}}
function renderHistory(){const chosenModel=$('#history-model').value, chosenVersion=$('#history-version').value, onlyCombo=$('#history-combo').checked;const visible=runs.filter(r=>(!chosenModel||r.config.model.id===chosenModel)&&(!chosenVersion||r.config.extraction.id===chosenVersion)&&(!onlyCombo||configKey(r.config)===configKey(getConfig())));$('#history-total').textContent=`${visible.length}개 기록 / 전체 ${runs.length}개`;
$('#history-list').innerHTML=visible.length?`<table><thead><tr><th>저장 시각 / 실행</th><th>모델 / 구조화 버전</th><th>환경</th><th>예시 결과</th><th>보기</th></tr></thead><tbody>${visible.map(r=>{const summary=counts(r);return `<tr><td><strong>${esc(new Date(r.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}</strong><small>${esc(r.id)} · 예시</small></td><td>${esc(r.config.model.name)}<small>${esc(methodName(r.config))} / ${esc(r.config.extraction.name)}</small></td><td>${esc(r.config.user)}<small>${esc(r.config.storageMode)}</small></td><td><span class="green">통과 ${summary.pass}</span> · 실패 ${summary.fail}<small>사람 판정 대기 ${summary.review} · 총 ${r.results.length}개</small></td><td><button class="button" data-open="${esc(r.id)}">결과 보기 ↗</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">저장된 결과가 없습니다.<br>선택한 환경에서 ‘결과 저장’ 또는 ‘전체 재생·저장’을 누르세요.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRun(b.dataset.open))}
function openRun(id){if(running){toast('현재 재생이 끝난 뒤 결과를 열어주세요.');return}const run=activeRuns().find(r=>r.id===id);if(!run)return;$('#model').value=run.config.model.id;$('#extract-version').value=run.config.extraction.id;$('#storage-mode').value=run.config.storageMode;$('#test-user').value=run.config.user;savedRunId=id;selected=cases.findIndex(c=>c.id===run.results[0].id);filter='all';query='';$('#search').value='';document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));tab='extraction';step=2;setView('tests');render();saveSettings()}
function setView(view){activeView=view;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));['tests','history','memory','search'].forEach(v=>$('#'+v+'-view').hidden=v!==view);const names={tests:'테스트 워크벤치',history:'실행 기록',memory:'기억 구조',search:'검색 구조'};$('#breadcrumb').textContent=names[view];$('#page-title').textContent={tests:'기억을 검증하는 가장 명확한 방법.',history:'선택별 결과를 보관하고, 다시 살펴보세요.',memory:'무엇을 기억하는지, 따로 확인하세요.',search:'어떤 기억을 찾았는지, 따로 확인하세요.'}[view];$('#page-desc').textContent={tests:'모델과 구조화 버전을 선택하고 결과를 로컬에 보관하세요.',history:'실행 기록을 조회하고, 삭제한 기록을 복원할 수 있습니다.',memory:'저장된 실행에서 기억 추출 후보와 기억 레코드를 모아 봅니다.',search:'저장된 실행에서 검색 질의·필터·후보·선택 결과를 모아 봅니다.'}[view];if(view==='history')renderHistory();if(view==='memory'||view==='search')renderCollection(view)}
// Memory and retrieval snapshots are independent so each stage can be inspected.
function activeRuns(){return runs.filter(r=>!r.deletedAt)}
function buildMemoryStructure(c,config){
  const extraction=c.extraction||fixture(c,config);
  return {schema_version:'memory-record-v1',is_demo:true,extraction_version:config.extraction.id,extracted_candidate:extraction,stored_records:c.memory?[{memory_id:c.id+'-memory',owner_id:c.id==='MEM-006'?'서연':config.user,content:c.memory,state:'active',source:{type:'fixed_fixture',scenario_id:c.id}}]:[]};
}
function buildSearchStructure(c,config){
  const relevant=!!c.memory && !['MEM-005','MEM-006'].includes(c.id);
  const memoryId=c.id+'-memory';
  return {schema_version:'retrieval-trace-v1',is_demo:true,query:{original:c.question,normalized:c.question,rewritten:false},filters:{owner_id:c.id==='MEM-006'?'민준':config.user,state:'active'},strategy:{method:'semantic',embedding_model:null,top_k:5,executed:false},candidates:relevant?[{memory_id:memoryId,content:c.memory,rank:1,score:null,selected:true}]:[],selected_memory_ids:relevant?[memoryId]:[],empty_reason:relevant?null:c.id==='MEM-005'?'직업과 관련된 기억 없음':c.id==='MEM-006'?'현재 사용자 범위에 해당하는 기억 없음':'저장된 기억 없음'};
}
function structuresFor(c,config){return {memory:c.memoryStructure||buildMemoryStructure(c,config),search:c.searchStructure||buildSearchStructure(c,config),legacy:!c.memoryStructure||!c.searchStructure}}
function structureJSON(value){return `<pre class="json-output">${esc(JSON.stringify(value,null,2))}</pre>`}
function detailStructure(kind,c,config){const data=structuresFor(c,config);return `<p class="json-caption">${kind==='memory'?'추출 후보와 저장된 기억 레코드를 구분합니다.':'검색 질의·사용자 필터·검색 후보·선택된 기억 ID를 확인합니다.'}<br>${data.legacy&&currentRun()?'기존 기록에 별도 구조가 없어 예시를 구성했습니다.':'고정 예시 · 실제 저장소 및 검색 엔진 미연결'}</p>${structureJSON(data[kind])}`}

function renderStructureInspector(){const c=currentCase(),config=currentRun()?.config||getConfig(),data=structuresFor(c,config);const isSearch=inspectorKind==='search';$('#inspector').innerHTML=`<div class="panel-title">구조 인스펙터 <span>독립된 예시 구조</span></div><div class="memory-tabs"><button data-inspector="memory" class="${!isSearch?'selected':''}">기억 구조</button><button data-inspector="search" class="${isSearch?'selected':''}">검색 구조</button></div>${isSearch?`<div class="memory-caption">검색 입력</div><div class="memory-card"><p>${esc(data.search.query.original)}</p><small>사용자 필터: ${esc(data.search.filters.owner_id)}<br>전략: 의미 검색 · top-k ${data.search.strategy.top_k}<br>임베딩 모델: 미연결</small></div><div class="memory-caption">검색 후보 · ${data.search.candidates.length}개</div>${data.search.candidates.map(item=>`<div class="memory-card"><div class="meta"><span>순위 ${item.rank} · 선택됨</span><span>점수 미측정</span></div><p>${esc(item.content)}</p><small>${esc(item.memory_id)}</small></div>`).join('')||'<p>'+esc(data.search.empty_reason)+'</p>'}`:`<div class="memory-caption">기억 추출 후보</div><p>${data.memory.extracted_candidate.facts?.length||0}개 사실 · ${esc(config.extraction.name)}</p><div class="memory-caption">저장된 기억 레코드 · ${data.memory.stored_records.length}개</div>${data.memory.stored_records.map(item=>`<div class="memory-card"><div class="meta"><span>${esc(item.memory_id)}</span><span>${esc(item.state)}</span></div><p>${esc(item.content)}</p><small>소유자: ${esc(item.owner_id)}</small></div>`).join('')||'<p>저장된 기억이 없습니다.</p>'}`}<div class="memory-note">기억은 저장할 내용과 상태를, 검색은 질문에서 기억을 찾는 과정을 보여줍니다. 모든 값은 UI 예시입니다.</div><button class="button" id="show-structure">${isSearch?'검색':'기억'} JSON 보기 →</button><button class="button" id="open-collection">${isSearch?'검색':'기억'} 구조 모아보기 ↗</button>`;document.querySelectorAll('[data-inspector]').forEach(b=>b.onclick=()=>{inspectorKind=b.dataset.inspector;renderStructureInspector()});$('#show-structure').onclick=()=>{tab=isSearch?'retrieval':'extraction';renderDetail()};$('#open-collection').onclick=()=>setView(isSearch?'search':'memory')}

function collectionRows(kind){const chosenMethod=$('#'+kind+'-method')?.value||'';const model=$('#'+kind+'-model').value,version=$('#'+kind+'-version').value,runId=$('#'+kind+'-run').value,text=$('#'+kind+'-query').value.toLowerCase();return activeRuns().filter(r=>(!chosenMethod||methodId(r.config)===chosenMethod)&&(!model||r.config.model.id===model)&&(!version||r.config.extraction.id===version)&&(!runId||r.id===runId)).flatMap(r=>r.results.map(c=>({run:r,result:c,structure:structuresFor(c,r.config)}))).filter(row=>JSON.stringify({name:row.result.name,id:row.result.id,structure:row.structure[kind],visualEvidence:evidenceFor(row.result,row.run.config),representation:row.result.representation||null}).toLowerCase().includes(text))}
function refreshRunOptions(kind){const select=$('#'+kind+'-run'),previous=select.value;select.innerHTML='<option value="">모든 실행</option>'+activeRuns().map(r=>`<option value="${esc(r.id)}">${esc(r.id)}</option>`).join('');if([...select.options].some(o=>o.value===previous))select.value=previous}
function renderCollection(kind){refreshRunOptions(kind);const rows=collectionRows(kind);$('#'+kind+'-total').textContent=`${rows.length}개 시나리오 구조 · ${new Set(rows.map(row=>row.run.id)).size}개 실행`;$('#'+kind+'-grid').innerHTML=rows.length?rows.map(({run:r,result:c,structure:s})=>`<article class="structure-card"><div class="structure-card-head"><span class="badge">${kind==='memory'?'기억 레코드':'검색 트레이스'} · 예시</span><span class="muted">${esc(c.id)}</span></div><h3>${esc(c.name)}</h3><p>${esc(r.config.model.name)}<br>${esc(methodName(r.config))} / ${esc(r.config.extraction.name)} · ${esc(r.config.user)}</p><small class="run-meta">${esc(r.id)}<br>${esc(new Date(r.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}</small>${kind==='memory'?`<div class="structure-summary"><strong>저장 기억 ${s.memory.stored_records.length}개</strong><p>${esc(s.memory.stored_records.map(record=>record.content).join(' / ')||'저장된 기억 없음')}</p><small>추출 후보 ${s.memory.extracted_candidate.facts?.length||0}개 사실</small></div>`:`<div class="structure-summary"><strong>질의: ${esc(s.search.query.original)}</strong><p>사용자: ${esc(s.search.filters.owner_id)} · 후보 ${s.search.candidates.length}개 · 선택 ${s.search.selected_memory_ids.length}개</p><small>${esc(s.search.empty_reason||'의미 검색 예시 · 점수 미측정')}</small></div>`}<details><summary>전체 ${kind==='memory'?'기억':'검색'} JSON 보기${s.legacy?' · 기존 기록의 파생 예시':''}</summary>${structureJSON(s[kind])}</details><button class="button" data-structure-run="${esc(r.id)}" data-structure-case="${esc(c.id)}" data-kind="${kind}">이 실행에서 보기 ↗</button></article>`).join(''):`<div class="empty collection-empty">${activeRuns().length?'조건에 맞는 구조가 없습니다.':'저장한 실행이 없습니다.'}<br>워크벤치에서 결과를 저장하면 ${kind==='memory'?'기억':'검색'} 구조가 이곳에 모입니다.</div>`;document.querySelectorAll('#'+kind+'-grid [data-structure-run]').forEach(b=>b.onclick=()=>{openRun(b.dataset.structureRun);selected=cases.findIndex(c=>c.id===b.dataset.structureCase);tab=b.dataset.kind==='memory'?'extraction':'retrieval';inspectorKind=b.dataset.kind;render()})}
function refreshCollections(){['memory','search'].forEach(renderCollection)}
function setupCollections(){for(const kind of ['memory','search']){const container=$('#'+kind+'-view');container.innerHTML=`<div class="section-heading"><div><h2>${kind==='memory'?'기억 구조':'검색 구조'} 모아보기</h2><p>${kind==='memory'?'모든 저장 실행의 추출 후보와 저장 기억을 모아서 확인합니다.':'모든 저장 실행의 질의·필터·검색 후보를 모아서 확인합니다.'}</p></div><button class="button" id="${kind}-export">↓ ${kind==='memory'?'기억':'검색'} 구조 내보내기</button></div><div class="collection-filters"><label>모델<select id="${kind}-model"><option value="">모든 모델</option>${models.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>추출 버전<select id="${kind}-version"><option value="">모든 버전</option>${versions.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></label><label>실행<select id="${kind}-run"></select></label><label>구조 내용 검색<input type="search" id="${kind}-query" placeholder="질문, 사실, 시나리오 검색"></label></div><div class="collection-heading"><span id="${kind}-total"></span><span>삭제한 실행은 제외됩니다.</span></div><div id="${kind}-grid" class="structure-grid"></div>`;['model','version','run'].forEach(field=>$('#'+kind+'-'+field).onchange=()=>renderCollection(kind));$('#'+kind+'-query').oninput=()=>renderCollection(kind);$('#'+kind+'-export').onclick=()=>{const items=collectionRows(kind).map(row=>({runId:row.run.id,config:row.run.config,scenarioId:row.result.id,derivedFromLegacy:row.structure.legacy,structure:row.structure[kind]}));showDownload({kind,exportedAt:new Date().toISOString(),is_demo:true,items},'memory-lab-'+kind+'-structures.json');toast('현재 필터에 맞는 구조를 내보냈습니다.')}}}

function historyVisibleRuns(){const chosenMethod=$('#history-method')?.value||'';const model=$('#history-model').value,version=$('#history-version').value,combo=$('#history-combo').checked,deleted=$('#history-status').value==='trash';return runs.filter(r=>Boolean(r.deletedAt)===deleted&&(!chosenMethod||methodId(r.config)===chosenMethod)&&(!model||r.config.model.id===model)&&(!version||r.config.extraction.id===version)&&(!combo||configKey(r.config)===configKey(getConfig())))}
function changeDeleted(ids,restore=false){if(running){toast('재생이 끝난 뒤 기록을 정리해 주세요.');return}const targets=new Set(ids);if(!targets.size)return;const now=new Date().toISOString();const next=runs.map(r=>targets.has(r.id)?{...r,deletedAt:restore?null:now}:r);if(!persist(next))return;if(!restore&&targets.has(savedRunId)){savedRunId=null;human={}}historySelection.clear();render();renderHistory();refreshCollections();toast(restore?`${targets.size}개 기록을 복원했습니다.`:`${targets.size}개 기록을 삭제했습니다. ‘삭제한 기록’에서 복원할 수 있습니다.`)}
function renderSavedHistory(){const visible=historyVisibleRuns(),deleted=$('#history-status').value==='trash';const visibleIds=new Set(visible.map(r=>r.id));historySelection=new Set([...historySelection].filter(id=>visibleIds.has(id)));$('#history-total').textContent=`${visible.length}개 표시 / 저장 ${activeRuns().length}개 · 삭제 ${runs.length-activeRuns().length}개`;$('#bulk-delete').textContent=deleted?'선택 기록 복원':'선택 기록 삭제';$('#bulk-delete').disabled=!historySelection.size||running;$('#selection-total').textContent=`${historySelection.size}개 선택`;
$('#history-list').innerHTML=visible.length?`<table><thead><tr><th><input id="select-visible" type="checkbox" aria-label="표시된 기록 전체 선택" ${historySelection.size===visible.length?'checked':''}></th><th>저장 시각 / 실행</th><th>모델 / 구조화 버전</th><th>예시 결과</th><th>관리</th></tr></thead><tbody>${visible.map(r=>{const s=counts(r);return `<tr><td><input type="checkbox" data-select-run="${esc(r.id)}" aria-label="${esc(r.id)} 선택" ${historySelection.has(r.id)?'checked':''}></td><td><strong>${esc(new Date(r.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}</strong><small>${esc(r.id)} · 예시${deleted?'<br>삭제됨 · 복원 가능':''}</small></td><td>${esc(r.config.model.name)}<small>${esc(methodName(r.config))} / ${esc(r.config.extraction.name)}<br>${esc(r.config.user)}</small></td><td><span class="green">통과 ${s.pass}</span> · 실패 ${s.fail}<small>사람 판정 대기 ${s.review} · 총 ${r.results.length}개</small></td><td><div class="row-actions">${deleted?'':`<button class="button" data-open="${esc(r.id)}">결과 보기 ↗</button>`}<button class="button ${deleted?'':'danger'}" data-delete-run="${esc(r.id)}">${deleted?'복원':'삭제'}</button></div></td></tr>`}).join('')}</tbody></table>`:`<div class="empty">${deleted?'삭제한 기록이 없습니다.':'조건에 맞는 저장 결과가 없습니다.'}</div>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRun(b.dataset.open));document.querySelectorAll('[data-delete-run]').forEach(b=>b.onclick=()=>changeDeleted([b.dataset.deleteRun],deleted));document.querySelectorAll('[data-select-run]').forEach(box=>box.onchange=()=>{box.checked?historySelection.add(box.dataset.selectRun):historySelection.delete(box.dataset.selectRun);renderSavedHistory()});if($('#select-visible')){$('#select-visible').indeterminate=historySelection.size>0&&historySelection.size<visible.length;$('#select-visible').onchange=e=>{historySelection=e.target.checked?new Set(visible.map(r=>r.id)):new Set();renderSavedHistory()}}}

// Evidence offsets refer to the original input; visual annotations never change saved outputs.
const evidenceRoles={person:'인물',relation:'관계·행동',value:'대상·값',time:'시간',negation:'부정',intent:'입력 의도'};
const evidenceSelections=new Map();
function buildVisualEvidence(c,config){
  const who=config.user.split(' · ')[0];
  let facts=[],pieces=[],links=[];
  const f=(id,subject,relation,value,note='명시된 사실',state='추출 후보')=>({id,subject,relation,value,note,state});
  const p=(quote,role,ids,from=0)=>({quote,role,ids,from});
  switch(c.id){
    case 'MEM-001':case 'MEM-002':
      facts=[f('F1',who,'선호','차','커피보다 차를 더 선호')];pieces=[p('나는','person',['F1']),p('커피','value',['F1']),p('차','value',['F1']),p('더 좋아해','relation',['F1'])];break;
    case 'MEM-003':
      facts=[f('F1',who,'선호','차','과거 정보','과거'),f('F2',who,'선호','커피','현재 선호로 갱신','현재')];
      pieces=[p('예전에는','time',['F1']),p('차','value',['F1']),p('좋아했는데','relation',['F1']),p('이제는','time',['F2']),p('커피','value',['F2']),p('더 좋아','relation',['F2'])];links=[{from:'F1',to:'F2',label:'갱신 · 과거 → 현재'}];break;
    case 'MEM-004':facts=[f('F1',who,'삭제 요청','음료 선호','사실 추가가 아닌 삭제 의도','삭제 요청')];pieces=[p('내','person',['F1']),p('음료 선호','value',['F1']),p('삭제해줘','intent',['F1'])];break;
    case 'MEM-005':facts=[f('F1',who,'활동','독서','직업을 의미하지 않음')];pieces=[p('나는','person',['F1']),p('주말마다','time',['F1']),p('책','value',['F1']),p('읽어','relation',['F1'])];break;
    case 'MEM-006':facts=[f('F1','서연','거주','부산','질문자는 민준 · 다른 사용자 범위','다른 사용자')];pieces=[p('서연','person',['F1']),p('나는','person',['F1']),p('부산','value',['F1']),p('살고 있어','relation',['F1'])];break;
    case 'MEM-007':facts=[f('F1',who,'공간 선호','조용한 곳','주어는 대화의 사용자'),f('F2',who,'주말 활동','독서','같은 사용자의 별도 사실')];pieces=[p('조용한 곳','value',['F1']),p('좋아하고','relation',['F1']),p('주말에는','time',['F2']),p('책','value',['F2']),p('읽어','relation',['F2'])];links=[{from:'F1',to:'F2',label:'같은 인물 · '+who}];break;
    case 'MEM-008':facts=[f('F1','사용자','이름','서연','이름은 원문에서 확인')];pieces=[p('내','person',['F1']),p('이름','relation',['F1']),p('서연','value',['F1'])];break;
    case 'MEM-009':
      facts=[f('F1',who,'선호','차','커피보다 차를 선호했던 과거','과거'),f('F2',who,'선호','커피','현재 유효한 선호','현재'),f('F3','민수','선호하지 않음','차','부정 표현을 보존 · 다른 인물','부정'),f('F4',who+'·민수','방문 계획','카페','장기 기억 저장 여부를 검토','일시적 계획')];
      pieces=[p('나는','person',['F1','F2']),p('예전에는','time',['F1']),p('커피','value',['F1']),p('차','value',['F1']),p('좋아했는데','relation',['F1']),p('요즘은','time',['F2']),p('커피','value',['F2'],c.input.indexOf('요즘은')),p('더 좋아','relation',['F2']),p('친구 민수','person',['F3']),p('차','value',['F3'],c.input.indexOf('친구')),p('좋아하지','relation',['F3']),p('않아','negation',['F3']),p('이번 주말','time',['F4']),p('민수','person',['F4'],c.input.indexOf('이번')),p('카페','value',['F4']),p('갈 생각','relation',['F4'])];links=[{from:'F1',to:'F2',label:'갱신 · 과거 → 현재'},{from:'F2',to:'F4',label:'같은 인물 · '+who},{from:'F3',to:'F4',label:'동행 인물 · 민수'}];break;
    default:{const extraction=c.extraction||fixture(c,config);facts=(extraction.facts||[]).map((item,i)=>f('F'+(i+1),item.subject,item.predicate,item.value));}
  }
  const spans=pieces.map(piece=>{const start=c.input.indexOf(piece.quote,piece.from);return {start,end:start+piece.quote.length,role:piece.role,factIds:piece.ids}}).filter(span=>span.start>=0);
  return {schemaVersion:'evidence-spans-v1',input:c.input,facts,spans,links,origin:'fixed-fixture-annotations'};
}
function evidenceFor(c,config){return c.visualEvidence?.schemaVersion==='evidence-spans-v1'&&c.visualEvidence.input===c.input?c.visualEvidence:buildVisualEvidence(c,config)}
function roleLegend(){return `<div class="evidence-legend" aria-label="하이라이트 역할 범례">${Object.entries(evidenceRoles).map(([role,label])=>`<span class="role-label role-${role}">${label}</span>`).join('')}</div>`}
function highlightedText(text,spans){
  const valid=spans.filter(s=>Number.isInteger(s.start)&&Number.isInteger(s.end)&&s.start>=0&&s.end<=text.length&&s.end>s.start);
  const boundaries=[...new Set([0,text.length,...valid.flatMap(s=>[s.start,s.end])])].sort((a,b)=>a-b);
  return boundaries.slice(0,-1).map((start,i)=>{const end=boundaries[i+1],segment=text.slice(start,end),matches=valid.filter(s=>s.start<=start&&s.end>=end);if(!matches.length)return esc(segment);const role=matches[0].role,ids=[...new Set(matches.flatMap(s=>s.factIds))];return `<button class="evidence-mark role-${esc(role)}" data-evidence-ids="${esc(ids.join(' '))}" data-evidence-role="${esc(role)}" aria-label="${esc(evidenceRoles[role])}: ${esc(segment)} · ${esc(ids.join(', '))}" aria-pressed="false"><span class="evidence-text">${esc(segment)}</span><small aria-hidden="true">${esc(evidenceRoles[role])}</small></button>`}).join('');
}
function evidenceSentences(input,evidence){
  const ranges=[];let cursor=0;
  // Keep punctuation in the original sentence; do not split decimal numbers.
  for(const match of input.matchAll(/[.!?。！？]+(?=\s|$)|\n+/gu)){const end=match.index+match[0].length;ranges.push([cursor,end]);cursor=end}
  if(cursor<input.length)ranges.push([cursor,input.length]);
  return ranges.map(([rawStart,rawEnd],index)=>{const raw=input.slice(rawStart,rawEnd),start=rawStart+(raw.length-raw.trimStart().length),end=rawEnd-(raw.length-raw.trimEnd().length);const spans=evidence.spans.filter(span=>span.start<end&&span.end>start);return {id:'S'+(index+1),start,end,text:input.slice(start,end),factIds:[...new Set(spans.flatMap(span=>span.factIds))],spans:spans.map(span=>({...span,start:Math.max(start,span.start)-start,end:Math.min(end,span.end)-start}))}}).filter(sentence=>sentence.text&&sentence.factIds.length);
}
function sentenceHighlights(sentence){
  const boundaries=[...new Set([0,sentence.text.length,...sentence.spans.flatMap(span=>[span.start,span.end])])].sort((a,b)=>a-b);
  return boundaries.slice(0,-1).map((start,index)=>{const end=boundaries[index+1],span=sentence.spans.find(item=>item.start<=start&&item.end>=end),text=esc(sentence.text.slice(start,end));return span?`<mark class="sentence-mark role-${esc(span.role)}">${text}</mark>`:text}).join('');
}
function extractedSentencesMarkup(c,evidence){const sentences=evidenceSentences(c.input,evidence);return `<section class="extracted-sentences"><div class="visual-label">원문에서 추출한 문장 <span>${sentences.length}개 · 원문 그대로</span></div>${sentences.map(sentence=>`<button class="extracted-sentence" data-source-facts="${esc(sentence.factIds.join(' '))}" aria-pressed="false"><span class="sentence-reference"><b>${sentence.id}</b><span>${esc(sentence.factIds.join(' · '))}</span></span><span class="sentence-quote">${sentenceHighlights(sentence)}</span><small>이 문장에서 추출된 사실 ${sentence.factIds.length}개 ↗</small></button>`).join('')||'<p class="implicit-note">원문에 직접 연결된 추출 문장이 없습니다.</p>'}<p class="sentence-note">사실 카드로 정리하기 전의 원문 문장입니다. 한 문장에서 여러 사실이 연결될 수 있습니다.</p></section>`}
function factSentenceReferences(c,evidence,fact){const sentences=evidenceSentences(c.input,evidence).filter(sentence=>sentence.factIds.includes(fact.id));return `<span class="fact-sentence-reference">추출 문장: ${sentences.length?sentences.map(sentence=>sentence.id).join(' · '):'직접 근거 없음'}</span>`}
document.addEventListener('click',event=>{const sentence=event.target.closest('[data-source-facts]');if(!sentence)return;updateEvidenceWidget(sentence.closest('[data-evidence-key]'),sentence.dataset.sourceFacts.split(' '));});

function evidenceMarkup(c,config,key,{compact=false}={}){
  const evidence=evidenceFor(c,config),data=structuresFor(c,config);
  return `<div class="evidence-widget ${compact?'compact-evidence':''}" data-evidence-key="${esc(key)}" data-scenario="${esc(c.id)}">${roleLegend()}<div class="evidence-layout"><svg class="evidence-arrows" aria-hidden="true"></svg><section class="source-panel"><div class="visual-label">사용자 원문 <span>고정 예시 주석</span></div><div class="evidence-source">${highlightedText(c.input,evidence.spans)}</div>${extractedSentencesMarkup(c,evidence)}<p class="implicit-note">${evidence.spans.some(span=>span.role==='person')?'색상과 역할 이름을 함께 표시합니다.':'주어가 생략된 문장입니다. 인물은 대화 사용자로 표시합니다.'}</p></section><div class="evidence-bridge" aria-hidden="true"><span>근거</span><b></b></div><section class="facts-panel"><div class="visual-label">추출된 사실과 연결</div>${evidence.facts.map(fact=>`<button class="evidence-fact" data-evidence-fact="${esc(fact.id)}" aria-pressed="false"><span class="fact-header"><b>${esc(fact.id)}</b><span>${esc(fact.state)}</span></span><span class="fact-triple"><span class="role-person">${esc(fact.subject)}</span><span class="triple-relation ${fact.state==='부정'?'negative-relation':''}">${esc(fact.relation)} →</span><span class="role-value">${esc(fact.value)}</span></span><small>${esc(fact.note)}</small>${factSentenceReferences(c,evidence,fact)}</button>`).join('')||'<p>추출된 사실이 없습니다.</p>'}</section></div>${evidence.links.length?`<div class="relation-lanes" aria-label="기억 사이의 관계">${evidence.links.map(link=>`<button class="relation-lane" data-link-from="${esc(link.from)}" data-link-to="${esc(link.to)}"><b>${esc(link.from)}</b><span>─ ${esc(link.label)} →</span><b>${esc(link.to)}</b></button>`).join('')}</div>`:''}<div class="evidence-selection" aria-live="polite">구절 또는 사실 카드를 선택해 연결된 근거를 확인하세요.</div><div class="stored-memory-strip"><span>저장 상태 · 예시</span><p>${esc(data.memory.stored_records.map(record=>record.content).join(' / ')||'저장된 기억 없음')}</p>${c.id==='MEM-003'?'<small class="mismatch-note">추출 후보는 커피인데 저장된 기억은 차입니다. 갱신 실패 예시를 그대로 표시합니다.</small>':''}</div></div>`;
}
function searchVisualMarkup(c,config,key,{compact=false}={}){
  const data=structuresFor(c,config),search=data.search;
  const used=new Set(search.selected_memory_ids||[]),candidates=search.candidates||[];
  const excluded=[];
  if(c.id==='MEM-006')excluded.push({id:'scope-excluded',text:'서연 · 부산 거주',reason:'다른 사용자 · 질문자는 민준'});
  if(c.id==='MEM-005')excluded.push({id:'topic-excluded',text:'주말마다 독서',reason:'직업 질문과 관련 없음'});
  if(c.id==='MEM-009'){excluded.push({id:'past-excluded',text:config.user.split(' · ')[0]+' · 과거 차 선호',reason:'현재 선호로 갱신된 정보'},{id:'person-excluded',text:'민수 · 차를 좋아하지 않음',reason:'질문 대상인 서연과 다른 인물'});}
  const q=search.query.original;
  const querySpans=[];
  for(const [word,role] of [['내','person'],['지금','time'],['취향','relation'],['좋아하는','relation'],['음료','value'],['직업','value'],['이름','value'],['사는 곳','value'],['이번 주말','time']]){const start=q.indexOf(word);if(start>=0)querySpans.push({start,end:start+word.length,role,factIds:['query']})}
  return `<div class="retrieval-visual" data-retrieval-key="${esc(key)}"><div class="visual-label">질문 → 검색 조건 → 기억 선택 → 답변 근거</div><div class="retrieval-query">${highlightedText(q,querySpans).replaceAll('data-evidence-ids="query"','data-query-token="true"')}</div><div class="retrieval-conditions"><div><small>인물</small><strong>${esc(search.filters.owner_id)}</strong></div><span>→</span><div><small>주제</small><strong>${c.id==='MEM-005'?'직업':c.id==='MEM-008'?'이름':c.id==='MEM-006'?'거주지':c.id==='MEM-007'?'주말 활동':'음료 선호'}</strong></div><span>→</span><div><small>상태</small><strong>${esc(search.filters.state==='active'?'현재 유효':search.filters.state)}</strong></div></div><div class="retrieval-paths"><div class="retrieval-candidates"><div class="visual-label">후보 · ${candidates.length}개 / 제외 예시 · ${excluded.length}개</div>${candidates.map(item=>`<button class="retrieval-candidate" data-candidate-id="${esc(item.memory_id)}" data-reason="${esc(used.has(item.memory_id)?'검색 결과에서 답변 근거로 선택된 기억입니다.':'후보에 포함되었지만 답변 근거로 선택되지 않았습니다.')}" aria-pressed="false"><span class="candidate-status">${used.has(item.memory_id)?'✓ 선택':'후보'}</span><strong>${esc(item.content)}</strong><small>${esc(item.memory_id)} · 점수 ${item.score==null?'미측정':esc(item.score)}</small></button>`).join('')}${excluded.map(item=>`<button class="retrieval-candidate excluded-candidate" data-candidate-id="${item.id}" data-reason="${esc(item.reason)}" aria-pressed="false"><span class="candidate-status">제외 · 설명용 예시</span><strong>${esc(item.text)}</strong><small>${esc(item.reason)}</small></button>`).join('')}${!candidates.length?`<div class="empty-retrieval">${esc(search.empty_reason||'검색된 기억 없음')}</div>`:''}</div><div class="retrieval-answer"><span class="path-arrow" aria-hidden="true">선택한 기억 ↓ 답변 근거</span><div class="answer-preview">${esc(c.answer)}</div><small>근거: ${used.size?esc([...used].join(', ')):'연결된 기억 없음'}</small>${c.id==='MEM-003'?'<p class="mismatch-note">이전 기억이 검색·사용된 실패 예시입니다.</p>':''}<div class="retrieval-reason" aria-live="polite">후보를 선택해 채택·제외 이유를 확인하세요.</div></div></div><details class="search-evidence"><summary>검색된 기억의 원문 근거와 관계 펼치기</summary>${evidenceMarkup(c,config,key+'-origin',{compact:true})}</details><p class="visual-footnote">의미 검색 설계 예시 · 임베딩·검색 미실행 · 제외 항목은 설명용이며 실제 검색 로그가 아닙니다.</p></div>`;
}
function rawStructureDetails(kind,c,config){const data=structuresFor(c,config);return `<details class="raw-structure"><summary>개발자용 ${kind==='memory'?'기억':'검색'} JSON 보기${data.legacy&&c.extraction?' · 기존 기록의 파생 예시':''}</summary>${structureJSON(data[kind])}</details>`}
function visualDetailStructure(kind,c,config){return (kind==='memory'?evidenceMarkup(c,config,'detail-'+c.id):searchVisualMarkup(c,config,'detail-search-'+c.id))+rawStructureDetails(kind,c,config)}
function visualConversation(c){const config=currentRun()?.config||getConfig();return `<div class="step-label"><strong>01 &nbsp; 기억 추출과 근거</strong><span>대화 A</span></div>${evidenceMarkup(c,config,'conversation-'+c.id)}<div class="divider">새 대화 · 기억 활용</div><div class="bubble">${esc(c.question)}</div>${step>=2?`<div class="bubble ai"><small>예시 응답</small>${esc(c.answer)}</div>`:'<p>다음 단계에서 회상 예시를 확인합니다.</p>'}`}
function visualInspector(){const c=currentCase(),config=currentRun()?.config||getConfig(),isSearch=inspectorKind==='search',data=structuresFor(c,config),evidence=evidenceFor(c,config);$('#inspector').innerHTML=`<div class="panel-title">연결 인스펙터 <span>예시</span></div><div class="memory-tabs"><button data-inspector="memory" class="${!isSearch?'selected':''}">기억 연결</button><button data-inspector="search" class="${isSearch?'selected':''}">검색 경로</button></div>${isSearch?`<div class="inspector-flow"><div>질문<br><strong>${esc(data.search.query.original)}</strong></div><span>↓ 대상 필터</span><div>${esc(data.search.filters.owner_id)}</div><span>↓ 검색 후보</span><div>${data.search.candidates.length}개 후보 → ${data.search.selected_memory_ids.length}개 선택</div><span>↓ 답변 근거</span><div>${esc(data.search.selected_memory_ids.join(', ')||'연결 없음')}</div></div>`:`${roleLegend()}<div class="inspector-facts">${evidence.facts.map(fact=>`<div><b>${esc(fact.id)}</b> ${esc(fact.subject)}<span> ─ ${esc(fact.relation)} → </span>${esc(fact.value)}</div>`).join('')}</div>${evidence.links.map(link=>`<div class="inspector-link">${esc(link.from)} → ${esc(link.to)}<small>${esc(link.label)}</small></div>`).join('')}`}<div class="memory-note">구절과 카드를 누르면 연결된 근거가 강조됩니다. 같은 색은 같은 역할이며, F 번호는 같은 사실을 뜻합니다.</div><button class="button" id="show-structure">${isSearch?'검색':'기억'} 연결 크게 보기 →</button><button class="button" id="open-collection">${isSearch?'검색':'기억'} 구조 모아보기 ↗</button>`;document.querySelectorAll('[data-inspector]').forEach(button=>button.onclick=()=>{inspectorKind=button.dataset.inspector;visualInspector()});$('#show-structure').onclick=()=>{tab=isSearch?'retrieval':'extraction';renderDetail()};$('#open-collection').onclick=()=>setView(isSearch?'search':'memory')}
function visualCollection(kind){refreshRunOptions(kind);const rows=collectionRows(kind);$('#'+kind+'-total').textContent=`${rows.length}개 시나리오 구조 · ${new Set(rows.map(row=>row.run.id)).size}개 실행`;$('#'+kind+'-grid').innerHTML=rows.length?rows.map(({run:r,result:c,structure:s})=>`<article class="structure-card visual-collection-card"><div class="structure-card-head"><span class="badge">${kind==='memory'?'원문 ↔ 기억':'질문 → 검색'} · 예시</span><span class="muted">${esc(c.id)}</span></div><div class="collection-card-title"><div><h3>${esc(c.name)}</h3><p>${esc(r.config.model.name)} · ${esc(methodName(r.config))} / ${esc(r.config.extraction.name)}</p></div><button class="button" data-structure-run="${esc(r.id)}" data-structure-case="${esc(c.id)}" data-kind="${kind}">이 실행에서 보기 ↗</button><button class="button relation-collection-link" data-related-run="${esc(r.id)}" data-related-source="${esc(c.id)}">다른 원문과의 관계 ↗</button></div><small class="run-meta">${esc(r.id)} · ${esc(new Date(r.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}${s.legacy?' · 기존 기록의 파생 예시':''}</small>${kind==='memory'?evidenceMarkup(c,r.config,'collection-'+r.id+'-'+c.id,{compact:true}):searchVisualMarkup(c,r.config,'search-'+r.id+'-'+c.id,{compact:true})}${rawStructureDetails(kind,c,r.config)}</article>`).join(''):`<div class="empty collection-empty">${activeRuns().length?'조건에 맞는 구조가 없습니다.':'저장한 실행이 없습니다.'}<br>결과를 저장하면 원문 하이라이트와 관계가 함께 표시됩니다.</div>`;document.querySelectorAll('#'+kind+'-grid [data-structure-run]').forEach(button=>button.onclick=()=>{if(running)return;openRun(button.dataset.structureRun);selected=cases.findIndex(c=>c.id===button.dataset.structureCase);tab=button.dataset.kind==='memory'?'extraction':'retrieval';inspectorKind=button.dataset.kind;render()});restoreEvidenceSelections()}

function drawEvidenceLinks(widget){
 const svg=widget.querySelector('.evidence-arrows'),layout=widget.querySelector('.evidence-layout'),selection=evidenceSelections.get(widget.dataset.evidenceKey);
 if(!svg||!layout)return;svg.replaceChildren();if(!selection?.ids?.length)return;
 const rect=layout.getBoundingClientRect(),source=widget.querySelector('.source-panel').getBoundingClientRect();if(!rect.width||!rect.height)return;
 const cards=[...widget.querySelectorAll('[data-evidence-fact]')].filter(card=>selection.ids.includes(card.dataset.evidenceFact));
 if(!cards.length||cards[0].getBoundingClientRect().left<source.right)return;
 svg.setAttribute('viewBox','0 0 '+rect.width+' '+rect.height);
 for(const card of cards){const target=card.getBoundingClientRect(),marks=[...widget.querySelectorAll('[data-evidence-ids]')].filter(mark=>mark.dataset.evidenceIds.split(' ').includes(card.dataset.evidenceFact));const chosen=marks.find(mark=>mark.classList.contains('role-focus'))||marks[0],mark=chosen?.getBoundingClientRect();if(!mark)continue;
 const x1=source.right-rect.left+2,y1=(mark.top+mark.bottom)/2-rect.top,x2=target.left-rect.left-3,y2=(target.top+target.bottom)/2-rect.top,middle=(x1+x2)/2;
 const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M'+x1+' '+y1+' C'+middle+' '+y1+' '+middle+' '+y2+' '+x2+' '+y2+' M'+(x2-5)+' '+(y2-4)+' L'+x2+' '+y2+' L'+(x2-5)+' '+(y2+4));svg.append(path);
 const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('cx',x1);dot.setAttribute('cy',y1);dot.setAttribute('r','3');svg.append(dot);
 }
}
window.addEventListener('resize',()=>document.querySelectorAll('[data-evidence-key]').forEach(drawEvidenceLinks));
document.addEventListener('toggle',event=>{if(event.target.tagName==='DETAILS'&&event.target.open)event.target.querySelectorAll('[data-evidence-key]').forEach(drawEvidenceLinks)},true);

function updateEvidenceWidget(widget,ids,role=null){const key=widget.dataset.evidenceKey,selection=new Set(ids);evidenceSelections.set(key,{ids,role});widget.querySelectorAll('[data-evidence-ids]').forEach(mark=>{const on=mark.dataset.evidenceIds.split(' ').some(id=>selection.has(id));mark.classList.toggle('evidence-active',on);mark.classList.toggle('role-focus',on&&role===mark.dataset.evidenceRole);mark.setAttribute('aria-pressed',String(on))});widget.querySelectorAll('[data-evidence-fact]').forEach(card=>{const on=selection.has(card.dataset.evidenceFact);card.classList.toggle('evidence-active',on);card.setAttribute('aria-pressed',String(on))});widget.querySelectorAll('[data-link-from]').forEach(link=>{const on=selection.has(link.dataset.linkFrom)||selection.has(link.dataset.linkTo);link.classList.toggle('evidence-active',on);link.setAttribute('aria-pressed',String(on))});widget.querySelectorAll('[data-source-facts]').forEach(sentence=>{const on=sentence.dataset.sourceFacts.split(' ').some(id=>selection.has(id));sentence.classList.toggle('evidence-active',on);sentence.setAttribute('aria-pressed',String(on))});const nativeScope=widget.closest('[data-native-scope]')||widget;nativeScope.querySelectorAll('[data-native-facts]').forEach(item=>{const on=item.dataset.nativeFacts.split(' ').some(id=>selection.has(id));item.setAttribute('aria-pressed',String(on))});const status=widget.querySelector('.evidence-selection');status.textContent=ids.length?`연결: ${ids.join(' ↔ ')}${role?' · 선택 역할: '+evidenceRoles[role]:''} · 강조된 구절이 해당 사실의 원문 근거입니다.`:'구절 또는 사실 카드를 선택해 연결된 근거를 확인하세요.';drawEvidenceLinks(widget);}
function restoreEvidenceSelections(){document.querySelectorAll('[data-evidence-key]').forEach(widget=>{const selection=evidenceSelections.get(widget.dataset.evidenceKey);if(selection)updateEvidenceWidget(widget,selection.ids,selection.role)})}
document.addEventListener('click',event=>{const mark=event.target.closest('[data-evidence-ids]'),fact=event.target.closest('[data-evidence-fact]'),link=event.target.closest('[data-link-from]');const trigger=mark||fact||link;if(trigger){const widget=trigger.closest('[data-evidence-key]');const ids=mark?mark.dataset.evidenceIds.split(' '):fact?[fact.dataset.evidenceFact]:[link.dataset.linkFrom,link.dataset.linkTo];updateEvidenceWidget(widget,ids,mark?.dataset.evidenceRole||null)}const candidate=event.target.closest('[data-candidate-id]');if(candidate){const region=candidate.closest('[data-retrieval-key]');region.querySelectorAll('[data-candidate-id]').forEach(button=>button.setAttribute('aria-pressed',String(button===candidate)));region.querySelector('.retrieval-reason').textContent=candidate.dataset.reason}const queryToken=event.target.closest('[data-query-token]');if(queryToken){const region=queryToken.closest('[data-retrieval-key]');region.querySelector('.retrieval-reason').textContent='질문에서 확인한 '+evidenceRoles[queryToken.dataset.evidenceRole]+': '+queryToken.querySelector('.evidence-text').textContent;}});

